import java.lang.annotation.*; import java.lang.reflect.*; import java.util.*;
@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface NotBlank {} @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface MaxLength { int value(); } @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface Run {} class SignupForm { @NotBlank @MaxLength(20) String username; SignupForm(String username) { this.username=username; } } class FormValidator { static List<String> validate(Object object) throws IllegalAccessException { List<String> errors=new ArrayList<>(); for(Field field:object.getClass().getDeclaredFields()) { field.setAccessible(true); String value=String.valueOf(field.get(object)); if(field.isAnnotationPresent(NotBlank.class) && value.isBlank()) errors.add(field.getName()+" must not be blank"); MaxLength max=field.getAnnotation(MaxLength.class); if(max != null && value.length()>max.value()) errors.add(field.getName()+" max length is "+max.value()); } return errors; } } class SampleTests { @Run void example() { System.out.println("annotated method ran"); } } public class Practical7Demo { public static void main(String[] args) throws Exception { System.out.println(FormValidator.validate(new SignupForm(""))); SampleTests tests=new SampleTests(); for(Method method:SampleTests.class.getDeclaredMethods()) if(method.isAnnotationPresent(Run.class)) method.invoke(tests); } }
